// This file is generated by AI.

// 「这次内容变动要不要补一次补全触发」的判据。
//
// 单独成纯函数是因为它曾经被写错过一次, 而那次的症状很隐蔽 (看起来只是"补全不自动弹了"):
//
// * 正确判据看**插入的文本**是否以触发字符结尾 —— 确认补全时语言服务会补上 `-motion=` 这类
//   片段, 结尾正是触发字符, 于是紧接着还能自动弹出参数值列表。
// * 写成"光标前那个字符是不是触发字符"就会把**删除**也算成触发: 删掉 `=x` 里的 `x` 之后,
//   光标前正好是 `=`。那会让服务端在无候选项的上下文里被问一次, 界面上冒出「No suggestions」。
//
// 手动输入触发字符不需要走这里: provider 的 `triggerCharacters` 由 Monaco 原生处理。

/** Monaco 的 `IModelContentChange` 只需要这一个字段, 便于单测直接构造。 */
export interface InsertedTextChange {
  /** 这次变动插入的文本; 删除操作为空串 */
  text: string;
}

/** 任一变动插入的文本以触发字符结尾时返回 true (删除与普通字符输入都返回 false)。 */
export function shouldRetriggerSuggest(
  changes: readonly InsertedTextChange[],
  triggerCharacters: ReadonlySet<string>
): boolean {
  return changes.some((change) => change.text.length > 0 && triggerCharacters.has(change.text.at(-1) ?? ''));
}

/**
 * 这次内容变动是不是"只有删除"。
 *
 * Monaco 只在**输入字符**时快速补全 (`quickSuggestions` 挂在 `onDidType` 上), 退格不会弹列表;
 * 我们额外补一次, 但只在纯删除时补 —— 插入字符已经由原生触发与 `shouldRetriggerSuggest` 覆盖,
 * 两者叠加会让同一个位置连开两次列表。
 */
export function isDeletionOnly(changes: readonly InsertedTextChange[]): boolean {
  return changes.length > 0 && changes.every((change) => change.text.length === 0);
}

/**
 * 删除之后, 光标停在这个位置还值不值得再补一次。
 *
 * 只给**删除**那一条入口用: 退格把光标退到行首 (`column === 1`) 时, 前面已经没有可补的上下文,
 * 弹出来的列表只会盖住上一行内容、还挡着用户继续退格。插入那条不设此限 —— 在行首敲触发字符
 * 照样该弹 (语句名就是这么补出来的)。
 *
 * 判的是**补全真正触发那一刻**的光标位置, 不是删除发生时的位置: 中间隔着一段防抖, 用户可能已经
 * 把光标移走了 (见 `ui/CodeEditor.svelte` 的 `scheduleSuggest`)。
 */
export function isSuggestableAfterDelete(position: { column: number } | null): boolean {
  return position !== null && position.column > 1;
}
